!function(){var m=document.getElementById("apd-mount");m&&(m.outerHTML="<style>.apd-cocin{margin:-4px 0 14px 36px;font-size:14px}.apd-cocin summary{cursor:pointer;color:var(--teal);font-weight:700}.apd-coc{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:12px 16px;margin-top:8px;max-height:320px;overflow:auto}.apd-coc b{display:block;margin:12px 0 4px}.apd-coc ul{padding-left:20px;margin:0}.apd-coc li{margin-bottom:5px}.apd-coc-sec{margin-top:26px}.apd-coc-sec .apd-coc{max-height:none}.apd-backnote a{color:var(--teal)!important;font-weight:700}</style><style>.apd-rep{margin-top:30px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:0 6px 24px rgba(23,35,30,.07)}.apd-rhead{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;background:var(--noir);color:#fff;border-radius:12px;padding:18px 22px;margin-bottom:16px}.apd-rhead .apd-serif{color:#fff!important;font-size:28px}.apd-rhead small{color:rgba(255,255,255,.75);font-size:13px}.apd-rhead b{color:#e9d8a6}.apd-rsum{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}.apd-rstat{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:12px;text-align:center}.apd-rstat b{display:block;font-family:'Cormorant Garamond',serif;font-size:32px;color:var(--teal);line-height:1.1}.apd-rstat span{font-size:13px;color:var(--muted)}.apd-rsub{font-size:12px;font-weight:900;letter-spacing:1.6px;text-transform:uppercase;color:var(--gold);margin:6px 0 10px}.apd-rcards{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:18px}.apd-rcard{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:16px;font-size:14px}.apd-rcard h4{font-family:'Cormorant Garamond',serif;font-size:23px;font-weight:600;margin:6px 0 2px;color:var(--noir)}.apd-rmeta{color:var(--muted);font-size:13px;margin:0 0 8px}.apd-rlog{margin:0 0 8px;color:var(--ink)}.apd-rline{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-top:1px solid #ece7da;gap:8px}.apd-dots{display:inline-flex;gap:4px}.apd-dots i{width:11px;height:11px;border-radius:50%;background:#e2ddcf;display:inline-block}.apd-dots i.on{background:var(--teal)}.apd-pill{display:inline-block;font-size:12px;font-weight:900;border-radius:999px;padding:3px 10px;white-space:nowrap}.apd-pill.full{background:var(--teal);color:#fff}.apd-pill.part{background:#e1efe9;color:#1f6b4f}.apd-pill.qry{background:#f6ecd8;color:#8a5a12}.apd-pill.no{background:#f3e3e3;color:var(--red)}.apd-rquote{background:var(--cream);border-left:3px solid var(--gold);padding:8px 10px;margin:8px 0 6px;border-radius:0 6px 6px 0}.apd-rquote b{display:block;font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:var(--gold)}.apd-rsend{font-size:13px;color:var(--ink);margin:6px 0 0}.apd-rno{display:grid;grid-template-columns:repeat(2,1fr);gap:0 18px;margin-bottom:12px}.apd-rno div{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:8px 0;border-top:1px solid #ece7da;font-size:14px}.apd-rno span small{color:var(--muted);display:block;font-size:12px}.apd-rfoot{font-size:13px;color:var(--muted);margin:6px 0 0!important}@media(max-width:760px){.apd-rsum{grid-template-columns:1fr 1fr}.apd-rcards,.apd-rno{grid-template-columns:1fr}.apd-rep{padding:14px}}.apd-select-note{font-size:15px;color:var(--ink);background:var(--paper);border-left:4px solid var(--gold);border-radius:8px;padding:10px 14px;margin:14px 0 0!important}.apd-how{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:30px}.apd-how-step{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px 22px 18px;position:relative}.apd-how-step b{position:absolute;top:-14px;left:20px;width:30px;height:30px;border-radius:50%;background:var(--gold);color:#fff;display:grid;place-items:center;font-size:15px}.apd-how-step h3{font-size:24px!important;margin:6px 0 8px!important}.apd-how-step p{color:var(--muted);font-size:15.5px;margin:0}.apd-how-note{font-size:14.5px;color:var(--muted);margin-top:16px}@media (max-width:720px){.apd-how{grid-template-columns:1fr}}.apd-close p{margin:0 auto 26px!important}.apd-dtabs{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 4px;margin:0 0 14px;-webkit-overflow-scrolling:touch}.apd-dtab{flex:1 0 128px;text-align:left;background:#fff!important;border:2px solid var(--line)!important;border-radius:12px;padding:10px 12px!important;color:var(--ink)!important;cursor:pointer}.apd-dtab b{display:block;font-size:16px;color:var(--noir)}.apd-dtab small{display:block;font-size:12.5px;color:var(--muted);margin-top:2px}.apd-dtab.apd-has small{color:var(--teal);font-weight:700}.apd-dtab[aria-selected=true]{border-color:var(--teal)!important;box-shadow:0 0 0 3px var(--teal-lt)}.apd-dhead{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:6px 14px;margin:0 0 10px}.apd-dhead b{font-size:17px;color:var(--noir)}.apd-allsum{margin-top:10px;font-size:14.5px;color:var(--ink)}.apd-welcome{display:none;background:var(--teal-lt);border-left:4px solid var(--teal);border-radius:12px;padding:14px 16px;margin:0 0 18px}.apd-welcome.apd-show{display:block}.apd-welcome p{margin:0 0 10px!important}.apd-welcome .apd-hero-ctas{margin:0;gap:8px}.apd-backnote{font-size:15px;color:var(--ink);background:var(--paper);border-left:4px solid var(--teal);border-radius:8px;padding:10px 14px;margin:-6px 0 22px!important}.apd-donenote{display:none;font-size:14.5px;color:var(--ink);background:var(--teal-lt);border-radius:8px;padding:9px 12px;margin:0 0 12px}.apd-donenote.apd-show{display:block}@media (min-width:981px){.apd-pay>.apd-card:last-child{grid-column:span 2}}.apd-sessdate{width:100%;font-size:12.5px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:6px 0 -2px}</style><div id=\"apd-root\"><header class=\"apd-hero\"><div class=\"apd-wrap\"><div class=\"apd-eyebrow\">StoryCraft Pitch Day · For literary agents</div><h1>Take pitches from home. <em>We handle everything else.</em></h1><p>One Friday and Saturday a quarter, in StoryCraft's Zoom rooms. Writers book ten-minute meetings inside the hours you choose, in your time zone, and you're paid for every pitch you take.</p><div class=\"apd-hero-ctas\"><a class=\"apd-btn apd-btn-gold\" href=\"#apd-form\">Sign up to take pitches</a><a class=\"apd-btn apd-btn-ghost\" data-apd-call href=\"#\" target=\"_blank\" rel=\"noopener\">Book a call with us</a></div><div class=\"apd-meta\"><span>Fri + Sat: May 14&ndash;15, Jun 11&ndash;12, Oct 15&ndash;16 &amp; Nov 12&ndash;13</span><span>10-minute 1:1 meetings in our Zoom rooms</span><span>You choose your days and hours</span><span>Paid by direct deposit (ACH)</span></div></div><div class=\"apd-hero-mark\" aria-hidden=\"true\">&ldquo;</div></header><section class=\"apd-sec\" id=\"apd-pay\"><div class=\"apd-wrap\"><div class=\"apd-eyebrow\">What you earn</div><h2 class=\"apd-h2\">Paid for every pitch you take.</h2><p class=\"apd-lede\">Your base fee covers each pitch on your schedule. If you'd like more, you can opt in to extra paid work on the sign-up form.</p><div class=\"apd-pay\"><div class=\"apd-card\"><div class=\"apd-num\"><span data-apd-rate=\"pitch\"></span><small>per pitch</small></div><h3>Every pitch</h3><p>Ten minutes with a writer who chose you from your wishlist.</p></div><div class=\"apd-card\"><span class=\"apd-tag\">Optional</span><div class=\"apd-num\"><span data-apd-rate=\"feedback\"></span><small>extra each</small></div><h3>Live Pre-Read sessions</h3><p>For writers who choose it instead of a pitch. Read their query letter and first 5 pages before the event, then use their ten minutes on the call for feedback and a request decision.</p></div><div class=\"apd-card\"><span class=\"apd-tag\">Optional</span><div class=\"apd-num\"><span data-apd-rate=\"qletter\"></span><small>each</small></div><h3>Written Query Letter feedback</h3><p>An upsell for writers who attended. After the event, read a writer's query letter and send back written notes before they submit to agents.</p></div><div class=\"apd-card\"><span class=\"apd-tag\">Optional</span><div class=\"apd-num\"><span data-apd-rate=\"pages\"></span><small>each</small></div><h3>Written First Pages feedback</h3><p>An upsell for writers who attended. After the event, read a writer's first 5 pages and send back written notes before they submit to agents.</p></div><div class=\"apd-card\"><div class=\"apd-num\"><span data-apd-days></span><small>days</small></div><h3>One direct deposit</h3><p>We pay by ACH within <span data-apd-days></span> days of Pitch Day. No invoices to send and no one to chase.</p></div></div><div class=\"apd-est\" aria-live=\"polite\"><div><h3>Estimate your day</h3><div class=\"apd-est-row\"><label id=\"apd-l-ep\">Pitches</label><div class=\"apd-step\" role=\"group\" aria-labelledby=\"apd-l-ep\"><button type=\"button\" data-apd-est=\"p|-1\" aria-label=\"Fewer pitches\">&minus;</button><output id=\"apd-ep\">12</output><button type=\"button\" data-apd-est=\"p|1\" aria-label=\"More pitches\">+</button></div></div><div class=\"apd-est-row\"><label id=\"apd-l-ef\">Of those, Live Pre-Read sessions</label><div class=\"apd-step\" role=\"group\" aria-labelledby=\"apd-l-ef\"><button type=\"button\" data-apd-est=\"f|-1\" aria-label=\"Fewer Live Pre-Read sessions\">&minus;</button><output id=\"apd-ef\">0</output><button type=\"button\" data-apd-est=\"f|1\" aria-label=\"More Live Pre-Read sessions\">+</button></div></div><div class=\"apd-est-row\"><label id=\"apd-l-eq\">Written Query Letter feedback</label><div class=\"apd-step\" role=\"group\" aria-labelledby=\"apd-l-eq\"><button type=\"button\" data-apd-est=\"q|-1\" aria-label=\"Fewer written query letters\">&minus;</button><output id=\"apd-eq\">0</output><button type=\"button\" data-apd-est=\"q|1\" aria-label=\"More written query letters\">+</button></div></div><div class=\"apd-est-row\"><label id=\"apd-l-ew\">Written First Pages feedback</label><div class=\"apd-step\" role=\"group\" aria-labelledby=\"apd-l-ew\"><button type=\"button\" data-apd-est=\"w|-1\" aria-label=\"Fewer written first pages\">&minus;</button><output id=\"apd-ew\">0</output><button type=\"button\" data-apd-est=\"w|1\" aria-label=\"More written first pages\">+</button></div></div></div><div class=\"apd-total\"><div class=\"apd-big\" id=\"apd-etotal\">$XYZ</div><small id=\"apd-ebreak\"></small></div></div><p class=\"apd-placeholder-note\" id=\"apd-phnote\">Final rates are being set. The calculator fills in once they're published.</p><p class=\"apd-select-note\">Paid extras are assigned based on how many writers sign up, so not every agent who opts in will be selected.</p></div></section><section class=\"apd-sec\" style=\"padding-top:0\"><div class=\"apd-wrap\"><div class=\"apd-eyebrow\">What we take off your plate</div><h2 class=\"apd-h2\">You show up and listen. We run the rest.</h2><div class=\"apd-grid3\"><div class=\"apd-card\"><div class=\"apd-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"17\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/></svg></div><h3>Your calendar fills itself</h3><p>Writers book their own slots inside the hours you open. You never send an invite or juggle a spreadsheet.</p></div><div class=\"apd-card\"><div class=\"apd-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5v14z\"/><path d=\"M8 7h8M8 11h6\"/></svg></div><h3>Writers come prepared</h3><p>Five days before the event, you get a one-page packet for each writer: logline, comps, genre and word count. Writers can take our self-paced pitching course or practice with a story coach first.</p></div><div class=\"apd-card\"><div class=\"apd-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/></svg></div><h3>Only your genres</h3><p>Writers filter by your wishlist and see your no-gos before they book, so the pitches you hear fit your list.</p></div><div class=\"apd-card\"><div class=\"apd-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M9 11l3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg></div><h3>A 60-second scorecard</h3><p>Right after each pitch session, tap through a short scorecard on your phone or computer while it's fresh. It becomes the writer's Pitch Report and your own Pitch Day Report.</p></div><div class=\"apd-card\"><div class=\"apd-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 11l18-8-8 18-2-8-8-2z\"/></svg></div><h3>We promote you</h3><p>Your photo, bio and wishlist go on the Pitch Day page and our social channels, in front of writers who are ready to query.</p></div><div class=\"apd-card\"><div class=\"apd-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.4 1.8.7 2.7a2 2 0 0 1-.5 2.1L8 9.8a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.7.7a2 2 0 0 1 1.7 2z\"/></svg></div><h3>A producer with you all day</h3><p>Writers wait in a green room, where a producer checks their camera and mic and brings them into your room. If a writer runs late or a link breaks, your producer sorts it out.</p></div></div><div class=\"apd-promise\"><img data-apd-pin alt=\"Certified Organic Storyteller pin\" loading=\"lazy\"><div><h3>Writers' work stays human.</h3><p>Every agent at Pitch Day commits to keeping writers' query letters, pages and pitches out of AI tools. We tell writers that promise on the booking page, and it's part of your contract.</p></div></div></div></section><section class=\"apd-sec\" style=\"padding-top:0\"><div class=\"apd-wrap\"><div class=\"apd-eyebrow\">How it works</div><h2 class=\"apd-h2\">From sign-up to payday.</h2><div class=\"apd-tl\"><div class=\"apd-card\"><h3>Before</h3><ol><li>Fill in the form below.</li><li>We email you a short contract.</li><li>Once it's signed, you get our ACH payment sign-up with a W-9.</li><li>We set up your StoryCraft account. Sign in to your Agent Portal on any device to update your wishlist, bio and hours, or add dates.</li><li>Your profile goes live once we launch the event, and writers start booking.</li><li>Five days before the event, your schedule and your packet with each writer's one-page appear in your Agent Portal.</li><li>If you're doing Live Pre-Read sessions, read those writers' query letters and first 5 pages before the event.</li></ol></div><div class=\"apd-card\"><h3>On Pitch Day</h3><ol><li>Join the StoryCraft Zoom from your schedule 15 minutes before your first time. A producer sets you up in your room.</li><li>Your producer brings each writer in from the green room. Writers pitch in 5 minutes or less, and the rest of the 10 minutes is yours for questions and feedback.</li><li>Tell each writer yes or no on requesting pages before the call ends.</li><li>Fill out the 60-second scorecard in the 5 minutes before your next writer, while it's fresh. The link sits under each writer's one-page.</li><li>Message your producer if anything comes up.</li></ol></div><div class=\"apd-card\"><h3>After</h3><ol><li>The evening of Pitch Day, you get your Pitch Day Report: every writer you requested, with their logline, your notes and how they're sending pages.</li><li>Writers you request send pages the way you tell us to.</li><li>If you signed up for written feedback, we send you query letters or first 5 pages from writers who bought it, so they can revise before they submit. These won't be writers whose pages you requested.</li><li>We pay you by ACH within <span data-apd-days></span> days.</li></ol></div></div></div></section><section class=\"apd-sec\" style=\"padding-top:0\"><div class=\"apd-wrap\"><div class=\"apd-eyebrow\">The 60-second scorecard</div><h2 class=\"apd-h2\">Score each pitch from your phone or computer.</h2><div class=\"apd-how\"><div class=\"apd-how-step\"><b>1</b><h3>Open your packet</h3><p>Five days before the event, your packet appears in your Agent Portal. Open it on your phone or computer: each writer's one-page in time order, with title, genre, word count, logline and comps.</p></div><div class=\"apd-how-step\"><b>2</b><h3>Tap \"Score this pitch\"</h3><p>The button sits under each writer's one-page. When the call ends, tap it. The scorecard opens with the writer's name and time already filled in.</p></div><div class=\"apd-how-step\"><b>3</b><h3>Tap, type, submit</h3><p>Tap your answers for hook, stakes, comps, category and length, fit and next step. Add one quick thing that's working and one quick thing to change. That's it.</p></div></div><p class=\"apd-how-note\">We combine your scorecard with the writer's other agents' scorecards into one Pitch Report. Your answers also build your own Pitch Day Report, below.</p></div></section><section class=\"apd-sec\" style=\"padding-top:0\" id=\"apd-report\"><div class=\"apd-wrap\"><div class=\"apd-eyebrow\">Your Pitch Day Report</div><h2 class=\"apd-h2\">Every writer you requested, in one place.</h2><p class=\"apd-lede\">The evening of Pitch Day, we turn your scorecards into your own report: who you asked for a full, a partial or a query with pages, a quick summary of each of those writers, and the writers you passed on. It's the agent's side of the Pitch Report writers get, so when requested pages arrive you know exactly who they're from.</p><div class=\"apd-rep\" role=\"region\" aria-label=\"Sample Pitch Day Report with fictional writers\"><div class=\"apd-rhead\"><div><div class=\"apd-serif\">Pitch Day Report</div><small>Sample · Saturday, May 15, 2027 · 12 pitches · Fictional writers</small></div><div style=\"text-align:right\"><small>Sent the evening of Pitch Day</small><br><b>4 requests</b></div></div><div class=\"apd-rsum\"><div class=\"apd-rstat\"><b>12</b><span>pitches heard</span></div><div class=\"apd-rstat\"><b>1</b><span>full requested</span></div><div class=\"apd-rstat\"><b>2</b><span>partials requested</span></div><div class=\"apd-rstat\"><b>1</b><span>asked to query with pages</span></div></div><div class=\"apd-rsub\">Writers you requested</div><div class=\"apd-rcards\"><div class=\"apd-rcard\"><span class=\"apd-pill full\">Full requested</span><h4>The Lantern Keeper's Daughter</h4><p class=\"apd-rmeta\">R. Okafor · 10:00 AM · Adult gothic historical · 96,000 words</p><p class=\"apd-rlog\">In 1890s Maine, a lighthouse keeper's daughter finds her drowned mother's diary and learns the shipwrecks the town blames on her family were planned.</p><div class=\"apd-rline\"><span>Your hook score</span><span class=\"apd-dots\" aria-label=\"Hook 4 of 4\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i></span></div><div class=\"apd-rquote\"><b>Your note</b>Slow-dread setup with a clear turn at the midpoint. Comps are right on.</div><p class=\"apd-rsend\"><b>Sending:</b> The full manuscript as a Word file to your email, subject line \"Pitch Day: The Lantern Keeper's Daughter.\"</p></div><div class=\"apd-rcard\"><span class=\"apd-pill part\">Partial requested</span><h4>Second Shift</h4><p class=\"apd-rmeta\">D. Lindqvist · 10:15 AM · Upmarket women's fiction · 84,000 words</p><p class=\"apd-rlog\">At 58, a night-shift nurse inherits her estranged sister's failing bakery and the teenage nephew who comes with it.</p><div class=\"apd-rline\"><span>Your hook score</span><span class=\"apd-dots\" aria-label=\"Hook 3 of 4\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i></i></span></div><div class=\"apd-rquote\"><b>Your note</b>Midlife reinvention with real warmth. I want to see if the voice holds past chapter one.</div><p class=\"apd-rsend\"><b>Sending:</b> First 50 pages through your QueryManager, with Pitch Day in the first line.</p></div><div class=\"apd-rcard\"><span class=\"apd-pill part\">Partial requested</span><h4>Salt and Ash</h4><p class=\"apd-rmeta\">J. Ramírez · 11:00 AM · Adult folk horror · 88,000 words</p><p class=\"apd-rlog\">When her grandmother dies, a Texas ER doctor goes home to bury her and finds the whole town keeping the same promise to something in the river.</p><div class=\"apd-rline\"><span>Your hook score</span><span class=\"apd-dots\" aria-label=\"Hook 4 of 4\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i></span></div><div class=\"apd-rquote\"><b>Your note</b>Culturally rooted horror with dread, not jump scares. Exactly my list.</div><p class=\"apd-rsend\"><b>Sending:</b> First 50 pages through your QueryManager, with Pitch Day in the first line.</p></div><div class=\"apd-rcard\"><span class=\"apd-pill qry\">Query me with pages</span><h4>Little Deaths</h4><p class=\"apd-rmeta\">A. Moreau · 1:15 PM · Domestic suspense · 79,000 words</p><p class=\"apd-rlog\">A hospice chaplain realizes the families she comforts keep losing a second person within the year.</p><div class=\"apd-rline\"><span>Your hook score</span><span class=\"apd-dots\" aria-label=\"Hook 3 of 4\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i></i></span></div><div class=\"apd-rquote\"><b>Your note</b>Strong hook. Needs a clearer antagonist before I read the full.</div><p class=\"apd-rsend\"><b>Sending:</b> A query with the first 10 pages through your QueryManager after revising.</p></div></div><div class=\"apd-rsub\">No request this time · 8</div><div class=\"apd-rno\"><div><span>The Ninth Orchard<small>9:00 AM · YA fantasy · 102,000</small></span><span class=\"apd-pill no\">Not for my list</span></div><div><span>Copper Saints<small>9:15 AM · Adult thriller · 125,000</small></span><span class=\"apd-pill no\">Not ready yet</span></div><div><span>What the Tide Keeps<small>9:45 AM · Women's fiction · 91,000</small></span><span class=\"apd-pill no\">Not for my list</span></div><div><span>The Glass Cartographer<small>10:45 AM · Adult fantasy · 110,000</small></span><span class=\"apd-pill no\">Not for my list</span></div><div><span>Long Way Home<small>11:15 AM · Memoir · 70,000</small></span><span class=\"apd-pill no\">Not ready yet</span></div><div><span>Hollow Year<small>11:30 AM · Adult horror · 85,000</small></span><span class=\"apd-pill no\">Not ready yet</span></div><div><span>Static<small>1:00 PM · Sci-fi thriller · 94,000</small></span><span class=\"apd-pill no\">Not for my list</span></div><div><span>The Glasshouse Son<small>1:30 PM · Literary fiction · 88,000</small></span><span class=\"apd-pill no\">Not for my list</span></div></div><p class=\"apd-rfoot\">Each requested writer's contact email and full intake (comps and project details) sit behind their name in the live report. Writers send pages the way you asked and mark them Pitch Day, so they're easy to match to this report.</p></div></div></section><section class=\"apd-sec apd-formsec\" id=\"apd-form\"><div class=\"apd-wrap apd-narrow\"><div class=\"apd-eyebrow\">Agent sign-up</div><h2 class=\"apd-h2\">Save your seat at the table.</h2><p class=\"apd-lede\">About 10 minutes. Your answers save on this device as you go, so you can step away and come back.</p><p class=\"apd-backnote\"><b>Already signed up?</b> <a href=\"/login\">Sign in to your Agent Portal</a> with your StoryCraft account to add Pitch Days or hours, or update your wishlist and bio, on any device.</p><div class=\"apd-success\" id=\"apd-success\" tabindex=\"-1\"><div class=\"apd-seal\" aria-hidden=\"true\">&#10003;</div><div class=\"apd-eyebrow\">You're on the list</div><h2>Thank you, <span id=\"apd-s-name\"></span>.</h2><p>We're thrilled to have you. Here's what happens next:</p><ol><li>We'll email a short contract to <b id=\"apd-s-email\"></b>.</li><li>Once it's signed, you'll get our ACH payment sign-up with a W-9, and we'll set up your StoryCraft account. Your profile goes live on the Pitch Day page when we launch the event.</li><li>Five days before Pitch Day, your final schedule and a packet for each writer appear in your Agent Portal.</li></ol><div class=\"apd-sum\" id=\"apd-s-sum\"></div><p class=\"apd-backnote\" style=\"text-align:left;max-width:560px;margin:0 auto 20px!important\"><b>Want more dates later?</b> Sign in to your Agent Portal on any device. Your details are already there, so you only pick the new days and hours.</p><div class=\"apd-hero-ctas\" style=\"justify-content:center\"><span id=\"apd-s-cals\" style=\"display:contents\"></span><button type=\"button\" class=\"apd-btn apd-btn-line\" data-apd-again>Add another date now</button><a class=\"apd-btn apd-btn-line\" data-apd-call href=\"#\" target=\"_blank\" rel=\"noopener\">Questions? Book a call</a></div></div><form id=\"apd-f\" novalidate><div class=\"apd-welcome\" id=\"apd-welcome\" role=\"status\"></div><div class=\"apd-progress\" aria-hidden=\"true\"><div class=\"apd-progress-in\"><span id=\"apd-ptext\">0 of 7 done</span><div class=\"apd-bar\"><i id=\"apd-pbar\"></i></div><span class=\"apd-saved\" id=\"apd-saved\"></span></div></div><fieldset class=\"apd-fs\" data-apd-sec=\"1\"><legend class=\"apd-sr\">About you</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">1</div><div><h3>About you</h3><p>How writers will see you, and how we reach you.</p></div></div><div class=\"apd-row\"><div class=\"apd-f\"><label for=\"apd-name\">Full name <span class=\"apd-req\">*</span></label><input class=\"apd-in\" id=\"apd-name\" data-k=\"name\" autocomplete=\"name\" data-req=\"text\"><div class=\"apd-err\">Please add your name.</div></div><div class=\"apd-f\"><label for=\"apd-pron\">Pronouns <span class=\"apd-opt\">(optional)</span></label><input class=\"apd-in\" id=\"apd-pron\" data-k=\"pronouns\" placeholder=\"she/her\"></div></div><div class=\"apd-row\"><div class=\"apd-f\"><label for=\"apd-email\">Preferred email <span class=\"apd-req\">*</span></label><input class=\"apd-in\" id=\"apd-email\" type=\"email\" data-k=\"email\" autocomplete=\"email\" data-req=\"email\"><div class=\"apd-help\">Where we send your contract, schedule and writer packets.</div><div class=\"apd-err\">Please add a valid email.</div></div><div class=\"apd-f\"><label for=\"apd-phone\">Phone number <span class=\"apd-req\">*</span></label><input class=\"apd-in\" id=\"apd-phone\" type=\"tel\" data-k=\"phone\" autocomplete=\"tel\" data-req=\"phone\"><div class=\"apd-help\">For day-of texts only. Never shared with writers.</div><div class=\"apd-err\">Please add a phone number we can text.</div></div></div><div class=\"apd-row3\"><div class=\"apd-f\"><label for=\"apd-agency\">Agency <span class=\"apd-req\">*</span></label><input class=\"apd-in\" id=\"apd-agency\" data-k=\"agency\" autocomplete=\"organization\" data-req=\"text\"><div class=\"apd-err\">Please add your agency.</div></div><div class=\"apd-f\"><label for=\"apd-title\">Title</label><select class=\"apd-in\" id=\"apd-title\" data-k=\"title\"><option>Literary Agent</option><option>Associate Agent</option><option>Junior Agent</option><option>Literary Manager</option><option>Agency Owner</option><option>Other</option></select></div><div class=\"apd-f\"><label for=\"apd-cc\">Assistant to cc <span class=\"apd-opt\">(optional)</span></label><input class=\"apd-in\" id=\"apd-cc\" type=\"email\" data-k=\"cc\" placeholder=\"Email\"></div></div></fieldset><fieldset class=\"apd-fs\" data-apd-sec=\"2\"><legend class=\"apd-sr\">Writers you'd like to meet</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">2</div><div><h3>Writers you'd like to meet</h3><p>Both are optional. You meet everyone in StoryCraft's Zoom rooms, so there's no meeting link to set up.</p></div></div><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optBeginner\"><div><b>Open to true beginners</b><span class=\"apd-d\">Writers who want practice or a conversation instead of a full pitch. Writers can filter for agents who tick this, and those meetings are marked in your packet.</span></div></label><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optProBono\"><div><b>Offer 2 pro-bono times <span class=\"apd-pay-pill\">Unpaid</span></b><span class=\"apd-d\">Set aside 2 of your times each Pitch Day for writers from historically underrepresented communities, including BIPOC and LGBTQ+ writers. We review applications, and approved writers book open pro-bono times first come, first served.</span></div></label></fieldset><fieldset class=\"apd-fs\" data-apd-sec=\"3\"><legend class=\"apd-sr\">Your Pitch Day dates and hours</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">3</div><div><h3>Your Pitch Day days and hours</h3><p>Each Pitch Day runs Friday and Saturday. Sign up for one day or several. Pick a day, then tap every hour you can take pitches, from 5 AM to 9 PM your time. Each hour fits up to four writers, with 5 minutes between each for your scorecard.</p></div></div><div class=\"apd-tzbar\"><span>Showing times in</span><label class=\"apd-sr\" for=\"apd-tz\">Your time zone</label><select class=\"apd-in\" id=\"apd-tz\" data-k=\"tz\"></select><span id=\"apd-tznote\"></span></div><div class=\"apd-dtabs\" id=\"apd-dtabs\" role=\"tablist\" aria-label=\"Pitch Day dates\"></div><div class=\"apd-dhead\"><b id=\"apd-dname\"></b><button type=\"button\" class=\"apd-mini\" data-apd-quick=\"copy\">Use these hours on every date</button></div><div class=\"apd-donenote\" id=\"apd-donenote\"></div><div class=\"apd-hours\" id=\"apd-hours\" role=\"group\" aria-label=\"Available hours\"></div><div class=\"apd-quick\"><button type=\"button\" class=\"apd-mini\" data-apd-quick=\"all\">Select all</button><button type=\"button\" class=\"apd-mini\" data-apd-quick=\"am\">Morning</button><button type=\"button\" class=\"apd-mini\" data-apd-quick=\"pm\">Afternoon</button><button type=\"button\" class=\"apd-mini\" data-apd-quick=\"eve\">Evening</button><button type=\"button\" class=\"apd-mini\" data-apd-quick=\"none\">Clear</button></div><div class=\"apd-err\" id=\"apd-hours-err\">Please choose at least one hour on at least one date.</div><div class=\"apd-caprow apd-light\"><div><span class=\"apd-lbl\" id=\"apd-l-cap\">Most pitches on this date</span><div class=\"apd-step\" role=\"group\" aria-labelledby=\"apd-l-cap\"><button type=\"button\" data-apd-cap=\"-1\" aria-label=\"Fewer\">&minus;</button><output id=\"apd-cap\">12</output><button type=\"button\" data-apd-cap=\"1\" aria-label=\"More\">+</button></div></div><div><label class=\"apd-lbl\" for=\"apd-brk\">15-minute break after every</label><select class=\"apd-in\" id=\"apd-brk\" data-k=\"brk\" style=\"width:auto;display:inline-block;padding:8px 12px!important\"><option value=\"4\">4 pitches</option><option value=\"6\" selected>6 pitches</option><option value=\"8\">8 pitches</option></select></div></div><div class=\"apd-sum\" id=\"apd-hsum\" aria-live=\"polite\"></div><div class=\"apd-allsum\" id=\"apd-allsum\"></div></fieldset><fieldset class=\"apd-fs\" data-apd-sec=\"4\"><legend class=\"apd-sr\">What you represent</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">4</div><div><h3>What you represent</h3><p>Tap once for <b>yes please</b>, twice for <b>no-go</b>, a third time to clear. Writers filter by these.</p></div></div><div class=\"apd-legend\"><span><i class=\"apd-dot y\"></i>Yes please</span><span><i class=\"apd-dot n\"></i>No-go</span><span><i class=\"apd-dot\"></i>Not set</span></div><div class=\"apd-sub\">Age category</div><div class=\"apd-chips\" data-apd-chips=\"age\"></div><div class=\"apd-sub\">Fiction</div><div class=\"apd-chips\" data-apd-chips=\"fic\"></div><div class=\"apd-sub\">Nonfiction</div><div class=\"apd-chips\" data-apd-chips=\"nf\"></div><div class=\"apd-err\" id=\"apd-genre-err\">Please mark at least one category or genre you want.</div><div><div class=\"apd-f\"><label for=\"apd-gnote\">Anything to add on genres? <span class=\"apd-opt\">(optional)</span></label><input class=\"apd-in\" id=\"apd-gnote\" data-k=\"genrenote\" placeholder=\"e.g. Romantasy only if the romance leads\"></div></div></fieldset><fieldset class=\"apd-fs\" data-apd-sec=\"5\"><legend class=\"apd-sr\">Wishlist and pitches</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">5</div><div><h3>Your wishlist and what you love in a pitch</h3><p>This is what writers read before they book you. Specifics bring you the right pitches.</p></div></div><div class=\"apd-f\"><label for=\"apd-mswl\">Detailed manuscript wishlist <span class=\"apd-req\">*</span><span class=\"apd-count\" id=\"apd-mswl-c\"></span></label><textarea class=\"apd-in\" id=\"apd-mswl\" data-k=\"mswl\" data-req=\"min:30\" rows=\"7\" placeholder=\"Tropes, themes, settings, comps you love, books you wish you'd represented, and what you're tired of seeing.\"></textarea><div class=\"apd-err\">Please give writers a bit more to go on (at least 30 words).</div></div><div class=\"apd-row\"><div class=\"apd-f\"><label for=\"apd-mswlurl\">MSWL or wishlist link <span class=\"apd-opt\">(optional)</span></label><input class=\"apd-in\" id=\"apd-mswlurl\" type=\"url\" data-k=\"mswlurl\" placeholder=\"https://\"></div><div class=\"apd-f\"><label for=\"apd-open\">Currently open to queries?</label><select class=\"apd-in\" id=\"apd-open\" data-k=\"open\"><option>Open to queries</option><option>Closed except for requests</option></select></div></div><div class=\"apd-f\"><label for=\"apd-likes\">What you enjoy in a pitch <span class=\"apd-req\">*</span></label><div class=\"apd-adds\" id=\"apd-adds\"></div><textarea class=\"apd-in\" id=\"apd-likes\" data-k=\"likes\" data-req=\"min:8\" rows=\"4\" placeholder=\"Tap a phrase above to add it, or write your own.\"></textarea><div class=\"apd-err\">Please tell writers a little about what makes a pitch work for you.</div></div><div class=\"apd-f\"><label for=\"apd-req\">How should writers send requested pages? <span class=\"apd-req\">*</span></label><textarea class=\"apd-in\" id=\"apd-req\" data-k=\"requests\" data-req=\"min:3\" rows=\"2\" style=\"min-height:70px\" placeholder=\"e.g. Through my QueryManager (link) with 'StoryCraft Pitch Day' in the subject line\"></textarea><div class=\"apd-help\">Include a link if needed, such as your QueryManager or submission form.</div><div class=\"apd-err\">Please tell writers how to send pages.</div></div></fieldset><fieldset class=\"apd-fs\" data-apd-sec=\"6\"><legend class=\"apd-sr\">Bio and headshot</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">6</div><div><h3>Bio and headshot</h3><p>For your profile on the Pitch Day page.</p></div></div><div class=\"apd-f\"><label for=\"apd-bio\">Short bio <span class=\"apd-req\">*</span><span class=\"apd-count\" id=\"apd-bio-c\"></span></label><textarea class=\"apd-in\" id=\"apd-bio\" data-k=\"bio\" data-req=\"min:20\" rows=\"5\" placeholder=\"Third person, 75 to 150 words: your agency, a few clients or sales, and what you're known for.\"></textarea><div class=\"apd-err\">Please add a short bio (at least 20 words).</div></div><span class=\"apd-lbl\">Headshot <span class=\"apd-req\">*</span></span><div class=\"apd-radios\" role=\"radiogroup\" aria-label=\"Headshot\"><label class=\"apd-rc\"><input type=\"radio\" name=\"apd-hs\" value=\"link\" data-k=\"hs\" checked>Paste a link<small>Drive, Dropbox or your website</small></label><label class=\"apd-rc\"><input type=\"radio\" name=\"apd-hs\" value=\"agency\" data-k=\"hs\">Use my agency photo<small>We'll take it from your agency's site</small></label><label class=\"apd-rc\"><input type=\"radio\" name=\"apd-hs\" value=\"email\" data-k=\"hs\">I'll email it<small>Attach it when you return the contract</small></label></div><div class=\"apd-f\" id=\"apd-hslink-wrap\"><label class=\"apd-sr\" for=\"apd-hslink\">Headshot link</label><input class=\"apd-in\" id=\"apd-hslink\" type=\"url\" data-k=\"hslink\" placeholder=\"https://link-to-your-headshot.jpg\"><div class=\"apd-help\">A square or portrait photo, at least 600 pixels wide. Please make sure the link is set so anyone can view it.</div><div class=\"apd-err\">Please paste a full link that starts with https://</div></div><div class=\"apd-f\"><label for=\"apd-links\">Website and social handles <span class=\"apd-opt\">(optional)</span></label><input class=\"apd-in\" id=\"apd-links\" data-k=\"links\" placeholder=\"agency page, Instagram, Bluesky, Threads...\"><div class=\"apd-help\">We tag you when we promote Pitch Day.</div></div></fieldset><fieldset class=\"apd-fs\" data-apd-sec=\"7\"><legend class=\"apd-sr\">Extra work and agreements</legend><div class=\"apd-fs-h\"><div class=\"apd-fs-n\">7</div><div><h3>Extra paid work and our agreements</h3><p>Opt in to anything that interests you. The agreements at the bottom are required.</p></div></div><p class=\"apd-select-note\" style=\"margin:0 0 14px!important\">Paid extras are assigned based on how many writers sign up, so not every agent who opts in will be selected.</p><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optFeedback\"><div><b>Live Pre-Read sessions <span class=\"apd-pay-pill\">+<span data-apd-rate=\"feedback\"></span> each</span></b><span class=\"apd-d\">For writers who choose it instead of a pitch. You read their query letter and first 5 pages before the event, then use their ten minutes on the call for feedback and a request decision.</span></div></label><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optQletter\"><div><b>Written Query Letter feedback <span class=\"apd-pay-pill\"><span data-apd-rate=\"qletter\"></span> each</span></b><span class=\"apd-d\">An upsell for writers who attended. After the event, read a writer's query letter and send back written notes before they submit to agents. These won't be writers whose pages you requested.</span></div></label><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optPages\"><div><b>Written First Pages feedback <span class=\"apd-pay-pill\"><span data-apd-rate=\"pages\"></span> each</span></b><span class=\"apd-d\">An upsell for writers who attended. After the event, read a writer's first 5 pages and send back written notes before they submit to agents. These won't be writers whose pages you requested.</span></div></label><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optSlam\"><div><b>First Pages Slam panel <span class=\"apd-pay-pill\"><span data-apd-rate=\"panel\"></span></span></b><span class=\"apd-d\">Saturday at 9:00 AM Pacific. A moderator reads writers' first pages aloud to you and two other agents, and you each say where you'd stop reading and why. We keep your pitch hours clear during the panel.</span></div></label><label class=\"apd-opt-card\"><input type=\"checkbox\" data-k=\"optTeach\"><div><b>Teach a StoryCraft Academy workshop <span class=\"apd-pay-pill\">$150 + commission</span></b><span class=\"apd-d\">Outside of Pitch Day, teach a live workshop for StoryCraft Academy members: a 60-minute presentation plus a 30-minute Q&amp;A, recorded for the Academy library. We pay $150, and you earn affiliate commission on sales. See examples on our <a href=\"https://www.storycraftacademy.org/booking\" target=\"_blank\" rel=\"noopener\">workshops page</a>. Tick this and we'll be in touch to talk through possible topics.</span><div class=\"apd-more\"><label class=\"apd-sr\" for=\"apd-topics\">Workshop topics</label><input class=\"apd-in\" id=\"apd-topics\" data-k=\"topics\" placeholder=\"Topics you'd love to teach (optional)\"></div></div></label><div class=\"apd-sub\" style=\"margin-top:22px\">Agreements <span class=\"apd-req\">*</span></div><div class=\"apd-ai\"><img data-apd-pin alt=\"Certified Organic Storyteller pin\" loading=\"lazy\"><p>Writers trust us with unpublished work. These promises protect them, and they're written into your contract.</p></div><label class=\"apd-agree\"><input type=\"checkbox\" data-k=\"agAI\" data-req=\"check\"><span><b>I will not put writers' material into any AI tool.</b> That includes query letters, pages, pitches, synopses and Pitch Day packets.</span></label><label class=\"apd-agree\"><input type=\"checkbox\" data-k=\"agChanges\" data-req=\"check\"><span><b>I'll tell StoryCraft as soon as possible</b> about any change to my hours or ability to attend.</span></label><label class=\"apd-agree\"><input type=\"checkbox\" data-k=\"agScore\" data-req=\"check\"><span><b>I'll fill out the 60-second scorecard</b> right after each pitch session ends.</span></label><label class=\"apd-agree\"><input type=\"checkbox\" data-k=\"agPrivate\" data-req=\"check\"><span><b>I'll keep writers' work private.</b> I won't record pitch sessions or share writers' materials outside my agency.</span></label><label class=\"apd-agree\"><input type=\"checkbox\" data-k=\"agPromo\" data-req=\"check\"><span><b>StoryCraft may feature my name, photo, bio and wishlist</b> on the Pitch Day page, in emails and on social media.</span></label><label class=\"apd-agree\"><input type=\"checkbox\" data-k=\"agConduct\" data-req=\"check\"><span><b>I agree to the Pitch Day Code of Conduct.</b> It covers writers, agents and our team.</span></label><details class=\"apd-cocin\"><summary>Read the Code of Conduct</summary><div class=\"apd-coc\"><p>Pitch Day only works if writers and agents both feel safe. This policy covers everyone at Pitch Day: writers, agents, producers and StoryCraft staff. It applies in the green room, agent rooms, the First Pages Slam, the Pitch Day forums, and any email or message connected to the event.</p><b>Not allowed</b><ul><li>Harassment of any kind, including comments about someone&#39;s race, ethnicity, religion, gender, gender identity, sexual orientation, disability, age, body or appearance</li><li>Sexual comments, advances or images</li><li>Threats, insults or shouting at anyone</li><li>Recording, screenshotting or sharing any session without everyone&#39;s consent</li><li>Contacting a writer or agent in ways they haven&#39;t invited, including personal social media accounts and phone numbers</li><li>Pressuring an agent to change a decision</li></ul><b>For agents</b><ul><li>Don&#39;t offer writers your own paid services, such as editing, coaching or consulting, during Pitch Day or in follow-ups.</li><li>We tell writers that your decisions are final and ask them not to email you to reconsider. If one does, let us know.</li></ul><b>Reporting a problem</b><p>Tell your producer during the event, or email <a href=\"mailto:hello@storycraftacademy.org\">hello@storycraftacademy.org</a> anytime. We read every report and won&#39;t share your name without your permission.</p><b>What happens next</b><p>We may end a session, remove anyone from Pitch Day without a refund or payment for that session, and bar them from future StoryCraft events.</p></div></details><div class=\"apd-err\" id=\"apd-agree-err\">Please check each agreement to continue.</div><div class=\"apd-f\" style=\"margin-top:16px\"><label for=\"apd-notes\">Anything else we should know? <span class=\"apd-opt\">(optional)</span></label><textarea class=\"apd-in\" id=\"apd-notes\" data-k=\"notes\" rows=\"3\" style=\"min-height:80px\" placeholder=\"Accessibility needs, a co-agent who'd like to join, questions for us...\"></textarea></div></fieldset><div class=\"apd-formerr\" id=\"apd-formerr\" role=\"alert\"></div><div class=\"apd-submit\"><p>After you submit this form, <b>we'll send you a contract with these agreements and payment information for you to sign</b>. Once it's signed, you'll get our ACH payment sign-up with a W-9. Nothing is final until you sign.</p><button type=\"submit\" class=\"apd-btn apd-btn-gold\" id=\"apd-go\">Sign me up</button></div><p class=\"apd-callrow\">Have questions first? <a data-apd-call href=\"#\" target=\"_blank\" rel=\"noopener\">Book a 30-minute call with us</a>.</p></form></div></section><section class=\"apd-sec\"><div class=\"apd-wrap apd-narrow\"><div class=\"apd-eyebrow\">Questions</div><h2 class=\"apd-h2\">Agent FAQ</h2><div class=\"apd-faq\" id=\"apd-faq\"></div><div class=\"apd-coc-sec\" id=\"apd-coc\"><div class=\"apd-eyebrow\">Code of Conduct</div><h2 class=\"apd-h2\">How everyone treats each other at Pitch Day.</h2><div class=\"apd-coc\"><p>Pitch Day only works if writers and agents both feel safe. This policy covers everyone at Pitch Day: writers, agents, producers and StoryCraft staff. It applies in the green room, agent rooms, the First Pages Slam, the Pitch Day forums, and any email or message connected to the event.</p><b>Not allowed</b><ul><li>Harassment of any kind, including comments about someone&#39;s race, ethnicity, religion, gender, gender identity, sexual orientation, disability, age, body or appearance</li><li>Sexual comments, advances or images</li><li>Threats, insults or shouting at anyone</li><li>Recording, screenshotting or sharing any session without everyone&#39;s consent</li><li>Contacting a writer or agent in ways they haven&#39;t invited, including personal social media accounts and phone numbers</li><li>Pressuring an agent to change a decision</li></ul><b>For agents</b><ul><li>Don&#39;t offer writers your own paid services, such as editing, coaching or consulting, during Pitch Day or in follow-ups.</li><li>We tell writers that your decisions are final and ask them not to email you to reconsider. If one does, let us know.</li></ul><b>Reporting a problem</b><p>Tell your producer during the event, or email <a href=\"mailto:hello@storycraftacademy.org\">hello@storycraftacademy.org</a> anytime. We read every report and won&#39;t share your name without your permission.</p><b>What happens next</b><p>We may end a session, remove anyone from Pitch Day without a refund or payment for that session, and bar them from future StoryCraft events.</p></div></div></div></section><section class=\"apd-close\"><div class=\"apd-wrap\"><h2>Rather talk it through?</h2><p>Book a 30-minute call with our team. We'll walk you through the day, the pay and anything else on your mind.</p><div class=\"apd-hero-ctas\"><a class=\"apd-btn apd-btn-gold\" data-apd-call href=\"#\" target=\"_blank\" rel=\"noopener\">Book a call</a><a class=\"apd-btn apd-btn-ghost\" href=\"#apd-form\">Go to the sign-up form</a></div></div></section></div>")}();
